window.DC_TPL='\n\n<div class="a0">\n  <a href="#main" class="a1">Skip to content</a>\n\n  <template data-sc="if" value="{{ hdrSpacer }}" hint-placeholder-val="{{ false }}"><div aria-hidden="true" class="a2"></div></template>\n  <header style="position:{{ hdrPos }};box-shadow:{{ hdrShadow }};animation:{{ hdrAnim }}" class="a3">\n    <div class="a4">\n      <button type="button" onclick="{{ goHome }}" aria-label="Design Atlas, home" class="a5">\n        <i class="ph ph-compass-rose a6" aria-hidden="true"></i>\n        <span class="a7">Design Atlas</span>\n      </button>\n      <template data-sc="if" value="{{ navWide }}" hint-placeholder-val="{{ true }}">\n        <nav aria-label="Primary" class="a8">\n          <template data-sc="for" list="{{ navItems }}" as="n" hint-placeholder-count="4">\n            <button type="button" onclick="{{ n.go }}" aria-current="{{ n.aria }}" style="border-bottom:2px solid {{ n.line }}" class="a9">{{ n.label }}</button>\n          </template>\n          <button type="button" onclick="{{ goShortlist }}" aria-label="{{ slAria }}" class="aa"><i class="ph ph-bookmarks-simple ab" aria-hidden="true"></i>Shortlist<template data-sc="if" value="{{ slHasCount }}"><span class="ac">{{ slCount }}</span></template></button>\n        </nav>\n\n      </template>\n      <button type="button" onclick="{{ quickTheme }}" aria-label="{{ themeLabel }}" title="{{ themeLabel }}" class="ad">\n        <template data-sc="if" value="{{ isDark }}" hint-placeholder-val="{{ false }}"><i class="ph ph-sun ae" aria-hidden="true"></i></template>\n        <template data-sc="if" value="{{ notDark }}" hint-placeholder-val="{{ true }}"><i class="ph ph-moon ae" aria-hidden="true"></i></template>\n      </button>\n      <template data-sc="if" value="{{ navNarrow }}">\n        <button type="button" onclick="{{ toggleMenu }}" aria-expanded="{{ menuAria }}" aria-controls="mobile-nav" aria-label="{{ menuLabel }}" style="color:{{ menuBtnFg }};background:{{ menuBtnBg }}" class="af"><i class="ph {{ menuIcon }} ae" aria-hidden="true"></i><span>{{ menuText }}</span></button>\n      </template>\n    </div>\n  </header>\n\n  <template data-sc="if" value="{{ navNarrow }}">\n    <div onclick="{{ closeMenu }}" aria-hidden="true" style="opacity:{{ menuFade }};pointer-events:{{ menuPE }}" class="ag"></div>\n    <nav id="mobile-nav" aria-label="Primary" style="opacity:{{ menuFade }};transform:translateY({{ menuY }});visibility:{{ menuVis }}" class="ah">\n      <template data-sc="for" list="{{ mobileNav }}" as="n">\n        <button type="button" onclick="{{ n.go }}" aria-current="{{ n.aria }}" class="ai"><i class="ph {{ n.icon }} aj" aria-hidden="true"></i><span class="ak">{{ n.label }}</span><template data-sc="if" value="{{ n.current }}"><span class="al">Current</span></template></button>\n      </template>\n      <button type="button" onclick="{{ goShortlist }}" class="am"><i class="ph ph-bookmarks-simple ab" aria-hidden="true"></i>Shortlist<template data-sc="if" value="{{ slHasCount }}"><span class="ac">{{ slCount }}</span></template></button>\n    </nav>\n  </template>\n\n  <div aria-hidden="true" style="opacity:{{ barOp }}" class="an"><span style="animation-play-state:{{ barPlay }}" class="ao"></span></div>\n  <main id="main" tabindex="-1" style="animation:{{ pageAnim }}" class="ap">\n    <template data-sc="if" value="{{ hasCrumbs }}">\n      <div class="aq">\n        <div class="ar">\n          <span class="as">\n            <button type="button" onclick="{{ navBack }}" disabled="{{ cantBack }}" aria-label="Go back" style="opacity:{{ backOp }}" class="at"><i class="ph ph-arrow-left ab" aria-hidden="true"></i></button>\n          </span>\n          <nav aria-label="Breadcrumb" class="au">\n            <ol class="av">\n              <template data-sc="for" list="{{ crumbs }}" as="c" hint-placeholder-count="3">\n                <li style="flex:{{ c.flex }}" class="aw">\n                  <template data-sc="if" value="{{ c.sep }}"><i class="ph ph-caret-right ax" aria-hidden="true"></i></template>\n                  <template data-sc="if" value="{{ c.link }}"><button type="button" onclick="{{ c.go }}" class="ay">{{ c.label }}</button></template>\n                  <template data-sc="if" value="{{ c.current }}"><span aria-current="page" class="az">{{ c.label }}</span></template>\n                </li>\n              </template>\n            </ol>\n          </nav>\n        </div>\n      </div>\n    </template>\n\n    <template data-sc="if" value="{{ isHome }}" hint-placeholder-val="{{ true }}">\n      <section id="hero" data-screen-label="Home" class="a10">\n        <div class="a11">\n          <h1 class="a12">Design resources, indexed with their licences.</h1>\n          <p class="a13">UI kits, design systems, icons, fonts and learning material. Each entry names its creator, the tools it works with and its terms of use, then links straight to the original source.</p>\n          <form role="search" onsubmit="{{ heroSubmit }}" class="a14">\n            <label for="hero-q" class="a15">Search resources</label>\n            <div class="a16">\n              <i class="ph ph-magnifying-glass a17" aria-hidden="true"></i>\n              <input id="hero-q" type="search" value="{{ heroQ }}" onchange="{{ onHeroQ }}" placeholder="Search kits, icons, fonts, guides" autocomplete="off" class="a18">\n            </div>\n            <button type="submit" class="a19">Search the index</button>\n          </form>\n          <div class="a1a">\n            <span class="a1b">Popular</span>\n            <div class="a1c">\n              <template data-sc="for" list="{{ quickSearches }}" as="s" hint-placeholder-count="5">\n                <button type="button" onclick="{{ s.go }}" class="a1d"><i class="ph ph-magnifying-glass a1e" aria-hidden="true"></i>{{ s.label }}</button>\n              </template>\n              <span aria-hidden="true" class="a1f"></span>\n            </div>\n          </div>\n        </div>\n        <div class="a1g">\n          <nav aria-label="Browse by category" onmouseenter="{{ heroPause }}" onmouseleave="{{ heroResume }}" onfocus="{{ heroPause }}" onblur="{{ heroResume }}" class="a1h">\n            <template data-sc="for" list="{{ heroTiles }}" as="t" hint-placeholder-count="10">\n              <button type="button" onclick="{{ t.go }}" onmouseenter="{{ t.hover }}" onfocus="{{ t.hover }}" aria-label="{{ t.aria }}" style="z-index:{{ t.z }};grid-column:{{ t.col }};color:{{ t.fg }};background:{{ t.bg }};border:1px solid {{ t.border }};box-shadow:{{ t.shadow }};transform:translateY({{ t.lift }}) scale({{ t.scale }})" class="a1i">\n                <i class="ph {{ t.icon }} a1j" aria-hidden="true"></i>\n                <span aria-hidden="true" style="left:{{ t.tipLeft }};opacity:{{ t.tipOp }};transform:translate({{ t.tipX }},{{ t.tipY }})" class="a1k">{{ t.label }}</span>\n              </button>\n            </template>\n          </nav>\n        </div>\n      </section>\n\n      <template data-sc="if" value="{{ homeLoading }}">\n        <p role="status" class="a1l"><i class="ph ph-circle-notch ae" aria-hidden="true"></i>Loading the catalog…</p>\n      </template>\n      <template data-sc="if" value="{{ homeError }}">\n        <div role="alert" class="a1m">\n          <div class="a1n">\n            <span class="a1o"><i class="ph ph-warning a1p" aria-hidden="true"></i>The catalog file couldn\'t be loaded.</span>\n            <button type="button" onclick="{{ retry }}" class="a1q">Try again</button>\n          </div>\n        </div>\n      </template>\n\n      <section aria-labelledby="idx-h" class="a1r">\n        <div class="a1s">\n          <h2 id="idx-h" class="a1t">The index</h2>\n          <span class="a1u">{{ indexSummary }}</span>\n        </div>\n        <ol class="a1v">\n          <template data-sc="for" list="{{ categoryIndex }}" as="c" hint-placeholder-count="10">\n            <li class="a1w">\n              <button type="button" onclick="{{ c.go }}" class="a1x">\n                <span class="a1y"><i class="ph {{ c.icon }} a1z" aria-hidden="true"></i></span>\n                <span class="a20">{{ c.label }}</span>\n                <span class="a21">{{ c.countLabel }}</span>\n                <span class="a22">{{ c.blurb }}</span>\n              </button>\n            </li>\n          </template>\n        </ol>\n      </section>\n\n      <template data-sc="if" value="{{ hasFeatured }}" hint-placeholder-val="{{ true }}">\n        <section aria-labelledby="feat-h" class="a23">\n          <h2 id="feat-h" class="a24">Worth starting with</h2>\n          <div class="a25">\n            <template data-sc="for" list="{{ featured }}" as="item" hint-placeholder-count="3">\n              <div><div class="a26">\n  <button type="button" onclick="{{ item.open }}" class="a27">\n    <template data-sc="if" value="{{ item.typographic }}" hint-placeholder-val="{{ true }}">\n      <div style="color:{{ item.coverFg }};background:{{ item.coverBg }}" class="a28">\n        <span class="a29"><i class="ph {{ item.icon }} ab" aria-hidden="true"></i><span>{{ item.catLabel }}</span></span>\n        <span class="a2a">\n          <span class="a2b">{{ item.name }}</span>\n          <span class="a2c"><img src="{{ item.logo }}" alt="" width="32" height="32" loading="lazy" decoding="async" class="a2d"></span>\n        </span>\n        <template data-sc="if" value="{{ item.shot }}"><img src="{{ item.shot }}" srcset="{{ item.shotSet }}" sizes="(min-width: 640px) 320px, 100vw" width="480" height="300" alt="{{ item.shotAlt }}" loading="lazy" decoding="async" fetchpriority="low" crossorigin="anonymous" data-raw="{{ item.shotRaw }}" onload="{{ item.shotLoad }}" onerror="{{ item.shotErr }}" class="a2e"><span aria-hidden="true" class="a2f"></span></template>\n      <template data-sc="if" value="{{ item.shot }}">\n        <span class="a2g"><i class="ph {{ item.icon }} a2h" aria-hidden="true"></i>{{ item.catLabel }}</span>\n      </template>\n      </div>\n      <template data-sc="if" value="{{ item.shot }}">\n        <div class="a2i">\n          <span class="a2j">{{ item.name }}</span>\n          <template data-sc="if" value="{{ item.hasCreator }}"><span class="a2k">by {{ item.creator }}</span></template>\n        </div>\n      </template>\n      <template data-sc="if" value="{{ item.noShot }}">\n        <template data-sc="if" value="{{ item.hasCreator }}"><div class="a2l">by {{ item.creator }}</div></template>\n      </template>\n    </template>\n    <template data-sc="if" value="{{ item.placeholder }}">\n      <div class="a2m">\n        <span class="a2n">preview image · {{ item.domain }}</span>\n      </div>\n      <div class="a2i">\n        <span class="a2o">{{ item.catLabel }}</span>\n        <span class="a2p">{{ item.name }}</span>\n        <template data-sc="if" value="{{ item.hasCreator }}"><span class="a1e">by {{ item.creator }}</span></template>\n      </div>\n    </template>\n    <div class="a2q">\n      <p class="a2r">{{ item.desc }}</p>\n    </div>\n    <div class="a2s">\n      <span class="a2t">\n        <span class="a2u">{{ item.price }}</span>\n        <span title="{{ item.comLabel }}" style="color:{{ item.comFg }}" class="a2v"><i class="ph {{ item.comIcon }} a2h" aria-hidden="true"></i>{{ item.comLabel }}</span>\n      </span>\n      <template data-sc="if" value="{{ item.hasTools }}"><span class="a2w">{{ item.toolsShort }}</span></template>\n    </div>\n  </button>\n  <template data-sc="if" value="{{ item.canSave }}">\n    <button type="button" onclick="{{ item.toggleSave }}" aria-pressed="{{ item.savedAria }}" aria-label="{{ item.saveLabel }}" title="{{ item.saveLabel }}" style="color:{{ item.saveFg }};background:{{ item.saveBg }};border:1.5px solid {{ item.saveBorder }}" class="a2x"><i class="ph {{ item.saveIcon }} ae" aria-hidden="true"></i></button>\n  </template>\n</div></div>\n            </template>\n          </div>\n        </section>\n      </template>\n\n      <section id="collections" aria-labelledby="coll-h" class="a2y">\n        <div class="a2z">\n          <h2 id="coll-h" class="a30">Start a project</h2>\n          <p class="a31">Pick what you\'re building. Each set covers the main needs with one resource each.</p>\n          <div class="a32">\n            <template data-sc="for" list="{{ collections }}" as="c" hint-placeholder-count="4">\n              <article class="a33">\n                <div>\n                  <h3 class="a34">{{ c.title }}</h3>\n                  <p class="a35">{{ c.desc }}</p>\n                </div>\n                <ul class="a36">\n                  <template data-sc="for" list="{{ c.picks }}" as="p">\n                    <li class="a37">\n                      <button type="button" onclick="{{ p.open }}" class="a38">\n                        <span class="a39"><i class="ph {{ p.icon }} ab" aria-hidden="true"></i></span>\n                        <span class="a3a">{{ p.need }}</span>\n                        <span class="a3b">{{ p.name }}</span>\n                        <span class="a3c">{{ p.price }}</span>\n                      </button>\n                    </li>\n                  </template>\n                </ul>\n                <div class="a3d">\n                  <button type="button" onclick="{{ c.compare }}" class="a3e"><i class="ph ph-columns ab" aria-hidden="true"></i>Compare this set</button>\n                  <button type="button" onclick="{{ c.go }}" class="a3f">Open as a list</button>\n                </div>\n              </article>\n            </template>\n          </div>\n        </div>\n      </section>\n\n      <section aria-labelledby="new-h" class="a2z">\n        <div class="a3g">\n          <h2 id="new-h" class="a1t">Recently added</h2>\n          <button type="button" onclick="{{ goExplore }}" class="a3h">Browse all {{ total }} entries</button>\n        </div>\n        <ul class="a3i">\n          <template data-sc="for" list="{{ latest }}" as="r" hint-placeholder-count="5">\n            <li class="a1w">\n              <button type="button" onclick="{{ r.open }}" class="a3j">\n                <span class="a3k"><i class="ph {{ r.icon }} a3l" aria-hidden="true"></i>{{ r.name }}</span>\n                <span class="a3m">{{ r.catLabel }}</span>\n                <span class="a3n">{{ r.price }}</span>\n                <span class="a3o">{{ r.dateOrCreator }}</span>\n              </button>\n            </li>\n          </template>\n        </ul>\n      </section>\n    </template>\n\n    <template data-sc="if" value="{{ isExplore }}">\n      <div data-screen-label="Explore">\n        <section class="a3p">\n          <div class="a3q">\n            <div class="a3r">\n              <template data-sc="if" value="{{ exHasIcon }}">\n                <span class="a3s"><i class="ph {{ exIcon }} a3t" aria-hidden="true"></i></span>\n              </template>\n              <h1 class="a3u">{{ exTitle }}</h1>\n            </div>\n            <p class="a3v">{{ exIntro }}</p>\n            <form role="search" onsubmit="{{ noSubmit }}" class="a3w">\n              <label for="ex-q" class="a3x">Search within {{ exScopeLabel }}</label>\n              <div class="a3y">\n                <i class="ph ph-magnifying-glass a3z" aria-hidden="true"></i>\n                <input id="ex-q" type="search" value="{{ q }}" onchange="{{ onQ }}" placeholder="Name, tag, creator or tool" autocomplete="off" class="a40">\n              </div>\n            </form>\n          </div>\n        </section>\n\n        <div class="a41">\n          <template data-sc="if" value="{{ narrow }}">\n            <button type="button" onclick="{{ toggleFilters }}" aria-expanded="{{ filtersAria }}" aria-controls="filters" class="a42"><i class="ph ph-funnel ab" aria-hidden="true"></i><span class="a43">{{ filtersLabel }}</span></button>\n          </template>\n          <template data-sc="if" value="{{ showFilters }}" hint-placeholder-val="{{ true }}">\n            <aside id="filters" aria-label="Filters" class="a44">\n              <fieldset class="a45">\n                <legend class="a46">Category</legend>\n                <template data-sc="for" list="{{ catOptions }}" as="o" hint-placeholder-count="11">\n                  <button type="button" onclick="{{ o.toggle }}" aria-pressed="{{ o.aria }}" style="font-weight:{{ o.weight }};background:{{ o.bg }}" class="a47">\n                    <i class="ph {{ o.icon }} a48" aria-hidden="true"></i><span class="ak">{{ o.label }}</span><span class="a49">{{ o.count }}</span>\n                  </button>\n                </template>\n              </fieldset>\n              <fieldset class="a45">\n                <legend class="a4a">Pricing</legend>\n                <div class="a4b">\n                  <template data-sc="for" list="{{ priceOptions }}" as="o" hint-placeholder-count="3">\n                    <button type="button" onclick="{{ o.toggle }}" aria-pressed="{{ o.aria }}" style="color:{{ o.fg }};background:{{ o.bg }}" class="a4c">{{ o.label }}</button>\n                  </template>\n                </div>\n              </fieldset>\n              <fieldset class="a45">\n                <legend class="a4a">Commercial use</legend>\n                <div class="a4b">\n                  <template data-sc="for" list="{{ comOptions }}" as="o" hint-placeholder-count="3">\n                    <button type="button" onclick="{{ o.toggle }}" aria-pressed="{{ o.aria }}" style="color:{{ o.fg }};background:{{ o.bg }}" class="a4d"><i class="ph {{ o.icon }} a4e" aria-hidden="true"></i>{{ o.label }}</button>\n                  </template>\n                </div>\n              </fieldset>\n              <fieldset class="a45">\n                <legend class="a4a">Works with</legend>\n                <div class="a4b">\n                  <template data-sc="for" list="{{ platOptions }}" as="o" hint-placeholder-count="6">\n                    <button type="button" onclick="{{ o.toggle }}" aria-pressed="{{ o.aria }}" style="color:{{ o.fg }};background:{{ o.bg }}" class="a4c">{{ o.label }}</button>\n                  </template>\n                </div>\n              </fieldset>\n              <p class="a4f">Pricing and licences are listed as each source published them. Confirm on the source before commercial use.</p>\n            </aside>\n          </template>\n\n          <section aria-labelledby="res-h" aria-busy="{{ busyAria }}" class="a4g">\n            <div class="a4h">\n              <h2 id="res-h" aria-live="polite" class="a4i"><template data-sc="if" value="{{ showSpin }}"><i class="ph ph-circle-notch a4j" aria-hidden="true"></i></template>{{ resultLabel }}</h2>\n              <div class="a4k">\n                <label for="sort" class="a4l">Sort</label>\n                <select id="sort" value="{{ sort }}" onchange="{{ onSort }}" class="a4m">\n                  <option value="relevance">Relevance</option>\n                  <option value="name">Name, A to Z</option>\n                  <option value="free">Free first</option>\n                </select>\n              </div>\n            </div>\n            <template data-sc="if" value="{{ hasChips }}">\n              <div class="a4n">\n                <template data-sc="for" list="{{ chips }}" as="c">\n                  <button type="button" onclick="{{ c.remove }}" aria-label="{{ c.aria }}" class="a4o">{{ c.label }}<i class="ph ph-x a2h" aria-hidden="true"></i></button>\n                </template>\n                <button type="button" onclick="{{ clearAll }}" class="a4p">Clear all</button>\n              </div>\n            </template>\n\n            <template data-sc="if" value="{{ isLoading }}">\n              <div class="a25">\n                <template data-sc="for" list="{{ loadingSlots }}" as="s">\n                  <div aria-hidden="true" class="a4q">\n                    <div class="a4r"></div>\n                    <div class="a4s">\n                      <div class="a4t"></div>\n                      <div class="a4u"></div>\n                      <div class="a4v"></div>\n                      <div class="a4w"></div>\n                      <div class="a4x"></div>\n                    </div>\n                  </div>\n                </template>\n              </div>\n            </template>\n\n            <template data-sc="if" value="{{ isError }}">\n              <div role="alert" class="a4y">\n                <h3 class="a4z"><i class="ph ph-warning a50" aria-hidden="true"></i>The catalog didn\'t load</h3>\n                <p class="a51">The resource list couldn\'t be fetched. Check your connection, then try again. Your search and filters are kept.</p>\n                <button type="button" onclick="{{ retry }}" class="a1q">Try again</button>\n              </div>\n            </template>\n\n            <template data-sc="if" value="{{ isEmpty }}">\n              <div class="a52">\n                <i class="ph ph-magnifying-glass a53" aria-hidden="true"></i>\n                <h3 class="a54">{{ emptyTitle }}</h3>\n                <p class="a55">Try a broader word, remove a filter, or browse one of these categories.</p>\n                <div class="a56">\n                  <template data-sc="if" value="{{ hasChips }}">\n                    <button type="button" onclick="{{ clearAll }}" class="a57">Clear filters</button>\n                  </template>\n                  <template data-sc="for" list="{{ suggestCats }}" as="c">\n                    <button type="button" onclick="{{ c.go }}" class="a58"><i class="ph {{ c.icon }}" aria-hidden="true"></i>{{ c.label }}</button>\n                  </template>\n                </div>\n                <p class="a59">Know a resource that belongs here? <button type="button" onclick="{{ goSubmit }}" class="a5a">Submit it for review</button>.</p>\n              </div>\n            </template>\n\n            <template data-sc="if" value="{{ hasResults }}" hint-placeholder-val="{{ true }}">\n              <div style="opacity:{{ resOp }};animation:{{ resAnim }}" class="a5b">\n                <template data-sc="for" list="{{ results }}" as="item" hint-placeholder-count="6">\n                  <div><div class="a26">\n  <button type="button" onclick="{{ item.open }}" class="a27">\n    <template data-sc="if" value="{{ item.typographic }}" hint-placeholder-val="{{ true }}">\n      <div style="color:{{ item.coverFg }};background:{{ item.coverBg }}" class="a28">\n        <span class="a29"><i class="ph {{ item.icon }} ab" aria-hidden="true"></i><span>{{ item.catLabel }}</span></span>\n        <span class="a2a">\n          <span class="a2b">{{ item.name }}</span>\n          <span class="a2c"><img src="{{ item.logo }}" alt="" width="32" height="32" loading="lazy" decoding="async" class="a2d"></span>\n        </span>\n        <template data-sc="if" value="{{ item.shot }}"><img src="{{ item.shot }}" srcset="{{ item.shotSet }}" sizes="(min-width: 640px) 320px, 100vw" width="480" height="300" alt="{{ item.shotAlt }}" loading="lazy" decoding="async" fetchpriority="low" crossorigin="anonymous" data-raw="{{ item.shotRaw }}" onload="{{ item.shotLoad }}" onerror="{{ item.shotErr }}" class="a2e"><span aria-hidden="true" class="a2f"></span></template>\n      <template data-sc="if" value="{{ item.shot }}">\n        <span class="a2g"><i class="ph {{ item.icon }} a2h" aria-hidden="true"></i>{{ item.catLabel }}</span>\n      </template>\n      </div>\n      <template data-sc="if" value="{{ item.shot }}">\n        <div class="a2i">\n          <span class="a2j">{{ item.name }}</span>\n          <template data-sc="if" value="{{ item.hasCreator }}"><span class="a2k">by {{ item.creator }}</span></template>\n        </div>\n      </template>\n      <template data-sc="if" value="{{ item.noShot }}">\n        <template data-sc="if" value="{{ item.hasCreator }}"><div class="a2l">by {{ item.creator }}</div></template>\n      </template>\n    </template>\n    <template data-sc="if" value="{{ item.placeholder }}">\n      <div class="a2m">\n        <span class="a2n">preview image · {{ item.domain }}</span>\n      </div>\n      <div class="a2i">\n        <span class="a2o">{{ item.catLabel }}</span>\n        <span class="a2p">{{ item.name }}</span>\n        <template data-sc="if" value="{{ item.hasCreator }}"><span class="a1e">by {{ item.creator }}</span></template>\n      </div>\n    </template>\n    <div class="a2q">\n      <p class="a2r">{{ item.desc }}</p>\n    </div>\n    <div class="a2s">\n      <span class="a2t">\n        <span class="a2u">{{ item.price }}</span>\n        <span title="{{ item.comLabel }}" style="color:{{ item.comFg }}" class="a2v"><i class="ph {{ item.comIcon }} a2h" aria-hidden="true"></i>{{ item.comLabel }}</span>\n      </span>\n      <template data-sc="if" value="{{ item.hasTools }}"><span class="a2w">{{ item.toolsShort }}</span></template>\n    </div>\n  </button>\n  <template data-sc="if" value="{{ item.canSave }}">\n    <button type="button" onclick="{{ item.toggleSave }}" aria-pressed="{{ item.savedAria }}" aria-label="{{ item.saveLabel }}" title="{{ item.saveLabel }}" style="color:{{ item.saveFg }};background:{{ item.saveBg }};border:1.5px solid {{ item.saveBorder }}" class="a2x"><i class="ph {{ item.saveIcon }} ae" aria-hidden="true"></i></button>\n  </template>\n</div></div>\n                </template>\n              </div>\n              <template data-sc="if" value="{{ hasMore }}">\n                <div ref="{{ moreRef }}" class="a5c">\n                  <span class="a1u">{{ shownLabel }}</span>\n                  <button type="button" onclick="{{ showMore }}" class="a5d">{{ moreLabel }}</button>\n                </div>\n              </template>\n            </template>\n          </section>\n        </div>\n      </div>\n    </template>\n\n    <template data-sc="if" value="{{ isDetail }}">\n      <article data-screen-label="Resource detail" class="a5e">\n        <div class="a5f">\n          <div class="a5g">\n            <h1 class="a5h">{{ d.name }}</h1>\n            <p class="a5i">By {{ d.creator }}</p>\n            <p class="a5j">{{ d.desc }}</p>\n            <a href="{{ d.url }}" target="_blank" rel="noopener" aria-label="{{ d.plateAria }}" class="a5k">\n              <span aria-hidden="true" class="a5l"></span>\n              <i class="ph {{ d.catIcon }} a5m" aria-hidden="true"></i>\n              <span class="a5n">\n                <span class="a5o">\n                  <span class="a5p"><i class="ph {{ d.catIcon }} a5q" aria-hidden="true"></i>{{ d.catLabel }}</span>\n                  <span class="a5r">Plate {{ d.plateNo }} / {{ d.plateOf }}</span>\n                </span>\n                <span class="a5s">\n                  <span class="a5t"><img src="{{ d.logo }}" alt="" width="64" height="64" loading="lazy" decoding="async" class="a5u"></span>\n                  <span class="a5v">\n                    <span class="a5w">{{ d.name }}</span>\n                    <span class="a5x">By {{ d.creator }}</span>\n                  </span>\n                </span>\n                <span class="a5y">\n                  <span class="a4b">\n                    <span class="a5z"><i class="ph ph-tag a4e" aria-hidden="true"></i>{{ d.price }}</span>\n                    <span class="a5z"><i class="ph {{ d.plateComIcon }} a4e" aria-hidden="true"></i>{{ d.plateCom }}</span>\n                  </span>\n                  <span class="a60">{{ d.domain }}<i class="ph ph-arrow-up-right ab" aria-hidden="true"></i></span>\n                </span>\n              </span>\n            </a>\n\n            <h2 class="a61">What\'s included</h2>\n            <ul class="a62">\n              <template data-sc="for" list="{{ d.features }}" as="f">\n                <li class="a63"><i class="ph ph-check a64" aria-hidden="true"></i><span>{{ f }}</span></li>\n              </template>\n            </ul>\n            <h2 class="a65">Useful for</h2>\n            <div class="a4b">\n              <template data-sc="for" list="{{ d.tagBtns }}" as="t">\n                <button type="button" onclick="{{ t.go }}" class="a66">{{ t.label }}</button>\n              </template>\n            </div>\n          </div>\n          <aside aria-label="Access and licence" class="a67">\n            <dl class="a68">\n              <dt class="a69"><i class="ph ph-tag" aria-hidden="true"></i>Pricing</dt><dd class="a6a">{{ d.price }}</dd>\n              <dt class="a69"><i class="ph ph-briefcase" aria-hidden="true"></i>Commercial use</dt><dd class="a6b"><i class="ph {{ d.comIcon }}" aria-hidden="true"></i>{{ d.comLabel }}</dd>\n              <dt class="a69"><i class="ph ph-scales" aria-hidden="true"></i>Licence</dt><dd class="a6c">{{ d.license }}</dd>\n              <dt class="a69"><i class="ph ph-file" aria-hidden="true"></i>Formats</dt><dd class="a6c">{{ d.formats }}</dd>\n              <dt class="a69"><i class="ph ph-plugs" aria-hidden="true"></i>Works with</dt><dd class="a6c">{{ d.tools }}</dd>\n              <dt class="a69"><i class="ph ph-globe" aria-hidden="true"></i>Source</dt><dd class="a6d">{{ d.domain }}</dd>\n              <dt class="a69"><i class="ph ph-calendar-check" aria-hidden="true"></i>Last checked</dt><dd style="color:{{ d.checkColor }}" class="a6c">{{ d.checkLabel }}</dd>\n            </dl>\n            <a href="{{ d.url }}" target="_blank" rel="noopener noreferrer" class="a6e">Visit the source<i class="ph ph-arrow-square-out ab" aria-hidden="true"></i><span class="a15"> (opens in a new tab)</span></a>\n            <button type="button" onclick="{{ d.toggleSave }}" aria-pressed="{{ d.savedAria }}" style="color:{{ d.saveFg }};background:{{ d.saveBg }}" class="a6f"><i class="ph {{ d.saveIcon }} ab" aria-hidden="true"></i>{{ d.saveText }}</button>\n            <p class="a6g">Licence as published by the creator. Terms can change, so check the source before using it commercially.</p>\n            <button type="button" onclick="{{ reportLink }}" class="a6h">Report a broken or outdated link</button>\n          </aside>\n        </div>\n        <template data-sc="if" value="{{ d.hasRelated }}">\n          <section aria-labelledby="rel-h" class="a6i">\n            <h2 id="rel-h" class="a6j">More in {{ d.catLabel }}</h2>\n            <div class="a25">\n              <template data-sc="for" list="{{ d.related }}" as="item">\n                <div><div class="a26">\n  <button type="button" onclick="{{ item.open }}" class="a27">\n    <template data-sc="if" value="{{ item.typographic }}" hint-placeholder-val="{{ true }}">\n      <div style="color:{{ item.coverFg }};background:{{ item.coverBg }}" class="a28">\n        <span class="a29"><i class="ph {{ item.icon }} ab" aria-hidden="true"></i><span>{{ item.catLabel }}</span></span>\n        <span class="a2a">\n          <span class="a2b">{{ item.name }}</span>\n          <span class="a2c"><img src="{{ item.logo }}" alt="" width="32" height="32" loading="lazy" decoding="async" class="a2d"></span>\n        </span>\n        <template data-sc="if" value="{{ item.shot }}"><img src="{{ item.shot }}" srcset="{{ item.shotSet }}" sizes="(min-width: 640px) 320px, 100vw" width="480" height="300" alt="{{ item.shotAlt }}" loading="lazy" decoding="async" fetchpriority="low" crossorigin="anonymous" data-raw="{{ item.shotRaw }}" onload="{{ item.shotLoad }}" onerror="{{ item.shotErr }}" class="a2e"><span aria-hidden="true" class="a2f"></span></template>\n      <template data-sc="if" value="{{ item.shot }}">\n        <span class="a2g"><i class="ph {{ item.icon }} a2h" aria-hidden="true"></i>{{ item.catLabel }}</span>\n      </template>\n      </div>\n      <template data-sc="if" value="{{ item.shot }}">\n        <div class="a2i">\n          <span class="a2j">{{ item.name }}</span>\n          <template data-sc="if" value="{{ item.hasCreator }}"><span class="a2k">by {{ item.creator }}</span></template>\n        </div>\n      </template>\n      <template data-sc="if" value="{{ item.noShot }}">\n        <template data-sc="if" value="{{ item.hasCreator }}"><div class="a2l">by {{ item.creator }}</div></template>\n      </template>\n    </template>\n    <template data-sc="if" value="{{ item.placeholder }}">\n      <div class="a2m">\n        <span class="a2n">preview image · {{ item.domain }}</span>\n      </div>\n      <div class="a2i">\n        <span class="a2o">{{ item.catLabel }}</span>\n        <span class="a2p">{{ item.name }}</span>\n        <template data-sc="if" value="{{ item.hasCreator }}"><span class="a1e">by {{ item.creator }}</span></template>\n      </div>\n    </template>\n    <div class="a2q">\n      <p class="a2r">{{ item.desc }}</p>\n    </div>\n    <div class="a2s">\n      <span class="a2t">\n        <span class="a2u">{{ item.price }}</span>\n        <span title="{{ item.comLabel }}" style="color:{{ item.comFg }}" class="a2v"><i class="ph {{ item.comIcon }} a2h" aria-hidden="true"></i>{{ item.comLabel }}</span>\n      </span>\n      <template data-sc="if" value="{{ item.hasTools }}"><span class="a2w">{{ item.toolsShort }}</span></template>\n    </div>\n  </button>\n  <template data-sc="if" value="{{ item.canSave }}">\n    <button type="button" onclick="{{ item.toggleSave }}" aria-pressed="{{ item.savedAria }}" aria-label="{{ item.saveLabel }}" title="{{ item.saveLabel }}" style="color:{{ item.saveFg }};background:{{ item.saveBg }};border:1.5px solid {{ item.saveBorder }}" class="a2x"><i class="ph {{ item.saveIcon }} ae" aria-hidden="true"></i></button>\n  </template>\n</div></div>\n              </template>\n            </div>\n          </section>\n        </template>\n      </article>\n    </template>\n\n    <template data-sc="if" value="{{ detailMissing }}">\n      <section data-screen-label="Resource not found" class="a6k">\n        <div class="a6l">\n          <i class="ph ph-map-trifold a6m" aria-hidden="true"></i>\n          <h1 class="a6n">This entry isn\'t in the index</h1>\n          <p class="a6o">It may have been renamed or removed after a recheck. Search for it, or browse the full index.</p>\n          <button type="button" onclick="{{ goExplore }}" class="a6p">Browse all {{ total }} entries</button>\n        </div>\n      </section>\n    </template>\n\n    <template data-sc="if" value="{{ isSubmit }}">\n      <div data-screen-label="Submit" class="a6q">\n        <div class="a6r">\n          <h1 class="a6s">Submit a resource</h1>\n          <p class="a6t">Every submission is reviewed by hand before it\'s listed. An entry is accepted when it has:</p>\n          <ol class="a6u">\n            <li class="a6v"><i class="ph ph-globe a6w" aria-hidden="true"></i><span><strong>A public source page.</strong> Nothing behind a login just to read what it is.</span></li>\n            <li class="a6v"><i class="ph ph-user a6w" aria-hidden="true"></i><span><strong>A named creator.</strong> A person, studio or organisation we can credit.</span></li>\n            <li class="a6v"><i class="ph ph-scales a6w" aria-hidden="true"></i><span><strong>Stated terms of use.</strong> A licence or pricing page that says what\'s allowed.</span></li>\n            <li class="a6v"><i class="ph ph-copy a6w" aria-hidden="true"></i><span><strong>Something new.</strong> Not already in the index under another name.</span></li>\n          </ol>\n        </div>\n        <div class="a6x">\n          <template data-sc="if" value="{{ subSent }}">\n            <div role="status" class="a6y">\n              <i class="ph ph-check-circle a6z" aria-hidden="true"></i>\n              <h2 class="a1t">It\'s in the review queue</h2>\n              <p class="a70">{{ subSentMsg }}</p>\n              <div class="a71">\n                <button type="button" onclick="{{ subReset }}" class="a72">Submit another</button>\n                <button type="button" onclick="{{ goExplore }}" class="a73">Back to the index</button>\n              </div>\n            </div>\n          </template>\n          <template data-sc="if" value="{{ subShowForm }}" hint-placeholder-val="{{ true }}">\n            <form novalidate="" onsubmit="{{ subSubmit }}" class="a74">\n              <template data-sc="if" value="{{ subFailed }}">\n                <div role="alert" class="a75"><strong class="a50">Your submission wasn\'t sent.</strong> The server didn\'t respond. Everything you entered is still here, so you can try again.</div>\n              </template>\n              <template data-sc="if" value="{{ subInvalid }}">\n                <div role="alert" class="a76"><strong class="a50">{{ subErrCount }}</strong> Fix the highlighted fields below.</div>\n              </template>\n              <div class="a77">\n                <label for="sub-name" class="a78">Resource name</label>\n                <input id="sub-name" value="{{ sub.name }}" onchange="{{ subOn.name }}" aria-invalid="{{ subAria.name }}" aria-describedby="sub-name-err" style="border:1.5px solid {{ subBorder.name }}" class="a79">\n                <span id="sub-name-err" class="a7a">{{ subErr.name }}</span>\n              </div>\n              <div class="a77">\n                <label for="sub-url" class="a78">Link to the original source</label>\n                <input id="sub-url" type="url" inputmode="url" value="{{ sub.url }}" onchange="{{ subOn.url }}" placeholder="https://" aria-invalid="{{ subAria.url }}" aria-describedby="sub-url-err" style="border:1.5px solid {{ subBorder.url }}" class="a79">\n                <span id="sub-url-err" class="a7a">{{ subErr.url }}</span>\n              </div>\n              <div class="a7b">\n                <div class="a7c">\n                  <label for="sub-cat" class="a78">Category</label>\n                  <select id="sub-cat" value="{{ sub.cat }}" onchange="{{ subOn.cat }}" aria-invalid="{{ subAria.cat }}" aria-describedby="sub-cat-err" style="border:1.5px solid {{ subBorder.cat }}" class="a7d">\n                    <option value="">Choose one</option>\n                    <template data-sc="for" list="{{ catSelect }}" as="c">\n                      <option value="{{ c.id }}">{{ c.label }}</option>\n                    </template>\n                  </select>\n                  <span id="sub-cat-err" class="a7a">{{ subErr.cat }}</span>\n                </div>\n                <div class="a7e">\n                  <label for="sub-price" class="a78">Pricing <span class="a7f">(optional)</span></label>\n                  <select id="sub-price" value="{{ sub.price }}" onchange="{{ subOn.price }}" class="a7g">\n                    <option value="">Not sure</option>\n                    <option value="Free">Free</option>\n                    <option value="Premium">Premium</option>\n                    <option value="Paid">Paid</option>\n                  </select>\n                </div>\n              </div>\n              <div class="a77">\n                <label for="sub-desc" class="a78">What is it, and who is it for?</label>\n                <textarea id="sub-desc" rows="4" value="{{ sub.desc }}" onchange="{{ subOn.desc }}" aria-invalid="{{ subAria.desc }}" aria-describedby="sub-desc-hint sub-desc-err" style="border:1.5px solid {{ subBorder.desc }}" class="a7h"></textarea>\n                <span id="sub-desc-hint" class="a1e">{{ subDescCount }}</span>\n                <span id="sub-desc-err" class="a7a">{{ subErr.desc }}</span>\n              </div>\n              <div class="a77">\n                <label for="sub-email" class="a78">Your email <span class="a7f">(optional, only to tell you the outcome)</span></label>\n                <input id="sub-email" type="email" autocomplete="email" value="{{ sub.email }}" onchange="{{ subOn.email }}" placeholder="email@example.com" aria-invalid="{{ subAria.email }}" aria-describedby="sub-email-err" style="border:1.5px solid {{ subBorder.email }}" class="a79">\n                <span id="sub-email-err" class="a7a">{{ subErr.email }}</span>\n              </div>\n              <button type="submit" disabled="{{ subSending }}" class="a7i">{{ subBtn }}</button>\n            </form>\n          </template>\n        </div>\n      </div>\n    </template>\n\n    <template data-sc="if" value="{{ isAbout }}">\n      <div data-screen-label="About">\n        <section class="a7j">\n          <h1 class="a7k">An index for people who make interfaces.</h1>\n          <div class="a7l">\n            <p class="a6c">Design Atlas collects UI kits, design systems, icons, typefaces, tools and learning material in one place, for designers, students and the developers who build what they draw.</p>\n            <p class="a6c">It doesn\'t host files or take a cut. Each entry is a short, checked description that points to the creator\'s own page, with the licence stated up front so you know what you can do before you click.</p>\n          </div>\n        </section>\n\n        <section aria-labelledby="faq-h" class="a7m">\n          <h2 id="faq-h" class="a7n">Questions</h2>\n          <div class="a7o">\n            <template data-sc="for" list="{{ faq }}" as="f" hint-placeholder-count="5">\n              <div class="a1w">\n                <h3 class="a6c">\n                  <button type="button" onclick="{{ f.toggle }}" aria-expanded="{{ f.aria }}" class="a7p">{{ f.q }}<i class="ph ph-caret-down a7q" aria-hidden="true" style="transform:rotate({{ f.rot }})"></i></button>\n                </h3>\n                <template data-sc="if" value="{{ f.open }}">\n                  <p class="a7r">{{ f.a }}</p>\n                </template>\n              </div>\n            </template>\n          </div>\n        </section>\n\n        <section id="contact" aria-labelledby="con-h" class="a7s">\n          <div class="a6r">\n            <h2 id="con-h" class="a7t">Contact</h2>\n            <p class="a7u">For broken links, licence corrections, or a creator asking to update their entry. To suggest something new, use <button type="button" onclick="{{ goSubmit }}" class="a5a">the submission form</button> instead.</p>\n          </div>\n          <div class="a7v">\n            <template data-sc="if" value="{{ conSent }}">\n              <div role="status" class="a6y">\n                <h3 class="a7w">Message sent</h3>\n                <p class="a70">Thanks, {{ con.name }}. A reply goes to {{ con.email }}.</p>\n                <button type="button" onclick="{{ conReset }}" class="a7x">Write another</button>\n              </div>\n            </template>\n            <template data-sc="if" value="{{ conShowForm }}" hint-placeholder-val="{{ true }}">\n              <form novalidate="" onsubmit="{{ conSubmit }}" class="a7y">\n                <template data-sc="if" value="{{ conFailed }}">\n                  <div role="alert" class="a76"><strong class="a50">Not sent.</strong> The server didn\'t respond. Your message is still here, so try again.</div>\n                </template>\n                <div class="a7z">\n                  <div class="a80">\n                    <label for="con-name" class="a78">Your name</label>\n                    <input id="con-name" autocomplete="name" value="{{ con.name }}" onchange="{{ conOn.name }}" aria-invalid="{{ conAria.name }}" aria-describedby="con-name-err" style="border:1.5px solid {{ conBorder.name }}" class="a79">\n                    <span id="con-name-err" class="a7a">{{ conErr.name }}</span>\n                  </div>\n                  <div class="a80">\n                    <label for="con-email" class="a78">Email</label>\n                    <input id="con-email" type="email" autocomplete="email" value="{{ con.email }}" onchange="{{ conOn.email }}" placeholder="email@example.com" aria-invalid="{{ conAria.email }}" aria-describedby="con-email-err" style="border:1.5px solid {{ conBorder.email }}" class="a79">\n                    <span id="con-email-err" class="a7a">{{ conErr.email }}</span>\n                  </div>\n                </div>\n                <div class="a77">\n                  <label for="con-msg" class="a78">Message</label>\n                  <textarea id="con-msg" rows="5" value="{{ con.msg }}" onchange="{{ conOn.msg }}" aria-invalid="{{ conAria.msg }}" aria-describedby="con-msg-err" placeholder="Which resource, and what\'s wrong?" style="border:1.5px solid {{ conBorder.msg }}" class="a7h"></textarea>\n                  <span id="con-msg-err" class="a7a">{{ conErr.msg }}</span>\n                </div>\n                <button type="submit" disabled="{{ conSending }}" class="a81">{{ conBtn }}</button>\n              </form>\n            </template>\n          </div>\n        </section>\n      </div>\n    </template>\n\n    <template data-sc="if" value="{{ isManage }}">\n      <div data-screen-label="Manage" class="a5e">\n        <div class="a82">\n          <div class="a83">\n            <h1 class="a84">Manage the hub</h1>\n            <p class="a85">{{ mgSummary }}</p>\n          </div>\n          <div class="a4b">\n            <button type="button" onclick="{{ exportJson }}" class="a86"><i class="ph ph-download-simple ab" aria-hidden="true"></i>Export JSON</button>\n            <button type="button" onclick="{{ pickImport }}" class="a58"><i class="ph ph-upload-simple ab" aria-hidden="true"></i>Import JSON</button>\n            <input id="import-file" type="file" accept="application/json,.json" onchange="{{ importJson }}" tabindex="-1" aria-hidden="true" class="a87">\n            <button type="button" onclick="{{ askReset }}" class="a58"><i class="ph ph-arrow-counter-clockwise ab" aria-hidden="true"></i>Reset to file</button>\n            <button type="button" onclick="{{ goHome }}" class="a88"><i class="ph ph-eye ab" aria-hidden="true"></i>View site</button>\n          </div>\n        </div>\n        <p class="a89"><i class="ph ph-info a8a" aria-hidden="true"></i><span>No database yet. Edits save in this browser and update the site right away, including other open tabs. Export the JSON to back it up, or replace atlas-data.json in the project to make it the default.</span></p>\n        <template data-sc="if" value="{{ confirmReset }}">\n          <div role="alertdialog" aria-labelledby="reset-h" class="a8b">\n            <span id="reset-h">Discard every change saved in this browser and reload atlas-data.json?</span>\n            <span class="a8c">\n              <button type="button" onclick="{{ doReset }}" class="a8d">Discard and reload</button>\n              <button type="button" onclick="{{ cancelReset }}" class="a8e">Cancel</button>\n            </span>\n          </div>\n        </template>\n\n        <div role="tablist" aria-label="Manage sections" class="a8f">\n          <template data-sc="for" list="{{ mgTabs }}" as="t" hint-placeholder-count="4">\n            <button type="button" role="tab" id="{{ t.tabId }}" aria-selected="{{ t.aria }}" aria-controls="mg-panel" onclick="{{ t.go }}" style="color:{{ t.fg }};background:{{ t.bg }}" class="a8g"><i class="ph {{ t.icon }} ab" aria-hidden="true"></i>{{ t.label }}<span class="a8h">{{ t.count }}</span></button>\n          </template>\n        </div>\n\n        <div id="mg-panel" role="tabpanel" aria-labelledby="{{ mgTabId }}" class="a8i">\n\n          <template data-sc="if" value="{{ tabRes }}" hint-placeholder-val="{{ true }}">\n            <div class="a8j">\n              <div class="a8k">\n                <div class="a8l">\n                  <div class="a8m">\n                    <label for="mg-q" class="a15">Filter resources</label>\n                    <i class="ph ph-magnifying-glass a8n" aria-hidden="true"></i>\n                    <input id="mg-q" type="search" value="{{ mgQ }}" onchange="{{ onMgQ }}" placeholder="Filter by name" class="a8o">\n                  </div>\n                  <label for="mg-cat" class="a15">Category</label>\n                  <select id="mg-cat" value="{{ mgCat }}" onchange="{{ onMgCat }}" class="a8p">\n                    <option value="">All categories</option>\n                    <template data-sc="for" list="{{ catSelect }}" as="c">\n                      <option value="{{ c.id }}">{{ c.label }}</option>\n                    </template>\n                  </select>\n                  <label for="mg-check" class="a15">Check status</label>\n                  <select id="mg-check" value="{{ mgCheck }}" onchange="{{ onMgCheck }}" class="a8q">\n                    <option value="">Any check status</option>\n                    <option value="due">{{ mgDueLabel }}</option>\n                  </select>\n                  <button type="button" onclick="{{ newRes }}" class="a8r"><i class="ph ph-plus" aria-hidden="true"></i>Add resource</button>\n                </div>\n                <p class="a8s">{{ mgCountLabel }}</p>\n                <template data-sc="if" value="{{ mgEmpty }}">\n                  <p class="a8t">No resources match this filter. Clear the search or pick another category.</p>\n                </template>\n                <ul class="a8u">\n                  <template data-sc="for" list="{{ mgRows }}" as="r" hint-placeholder-count="8">\n                    <li style="background:{{ r.bg }}" class="a8v">\n                      <i class="ph {{ r.icon }} a3l" aria-hidden="true"></i>\n                      <span class="a8w"><span class="a78">{{ r.name }}</span><span class="a1e">{{ r.meta }}</span></span>\n                      <template data-sc="if" value="{{ r.confirming }}">\n                        <span class="a8x">\n                          <span>Delete?</span>\n                          <button type="button" onclick="{{ r.del }}" class="a8y">Delete</button>\n                          <button type="button" onclick="{{ r.cancelDel }}" class="a8z">Keep</button>\n                        </span>\n                      </template>\n                      <template data-sc="if" value="{{ r.idle }}" hint-placeholder-val="{{ true }}">\n                        <span class="a90">\n                          <button type="button" onclick="{{ r.edit }}" aria-label="{{ r.editAria }}" class="a91"><i class="ph ph-pencil-simple" aria-hidden="true"></i>Edit</button>\n                          <button type="button" onclick="{{ r.askDel }}" aria-label="{{ r.delAria }}" class="a92"><i class="ph ph-trash ab" aria-hidden="true"></i></button>\n                        </span>\n                      </template>\n                    </li>\n                  </template>\n                  <template data-sc="if" value="{{ mgMore }}">\n                    <li class="a93"><button type="button" onclick="{{ mgShowMore }}" class="a94">{{ mgMoreLabel }}</button></li>\n                  </template>\n                </ul>\n              </div>\n\n              <div class="a95">\n                <template data-sc="if" value="{{ noEditor }}" hint-placeholder-val="{{ true }}">\n                  <div class="a96">\n                    <i class="ph ph-note-pencil a6m" aria-hidden="true"></i>\n                    <p class="a97">Choose Edit on any resource, or add a new one. A live card preview appears here as you type.</p>\n                  </div>\n                </template>\n                <template data-sc="if" value="{{ hasEditor }}">\n                  <form novalidate="" onsubmit="{{ saveRes }}" aria-labelledby="ed-h" class="a98">\n                    <div class="a99">\n                      <h2 id="ed-h" class="a34">{{ edTitle }}</h2>\n                      <button type="button" onclick="{{ closeEditor }}" aria-label="Close editor" class="a9a"><i class="ph ph-x ab" aria-hidden="true"></i></button>\n                    </div>\n                    <template data-sc="if" value="{{ edFromSub }}">\n                      <p class="a9b">Filled from a submission. Check the licence and creator on the source, then save to publish it.</p>\n                    </template>\n                    <div class="a77">\n                      <label for="ed-name" class="a78">Name</label>\n                      <input id="ed-name" value="{{ ed.name }}" onchange="{{ edOn.name }}" aria-invalid="{{ edAria.name }}" style="border:1.5px solid {{ edBorder.name }}" class="a9c">\n                      <span class="a7a">{{ edErr.name }}</span>\n                    </div>\n                    <div class="a77">\n                      <label for="ed-url" class="a78">Source URL</label>\n                      <input id="ed-url" type="url" value="{{ ed.url }}" onchange="{{ edOn.url }}" placeholder="https://" aria-invalid="{{ edAria.url }}" style="border:1.5px solid {{ edBorder.url }}" class="a9c">\n                      <span class="a7a">{{ edErr.url }}</span>\n                    </div>\n                    <div class="a9d">\n                      <div class="a80">\n                        <label for="ed-cat" class="a78">Category</label>\n                        <select id="ed-cat" value="{{ ed.cat }}" onchange="{{ edOn.cat }}" aria-invalid="{{ edAria.cat }}" style="border:1.5px solid {{ edBorder.cat }}" class="a9e">\n                          <option value="">Choose one</option>\n                          <template data-sc="for" list="{{ catSelect }}" as="c">\n                            <option value="{{ c.id }}">{{ c.label }}</option>\n                          </template>\n                        </select>\n                        <span class="a7a">{{ edErr.cat }}</span>\n                      </div>\n                      <div class="a9f">\n                        <label for="ed-price" class="a78">Pricing</label>\n                        <select id="ed-price" value="{{ ed.price }}" onchange="{{ edOn.price }}" class="a9g">\n                          <option value="Free">Free</option>\n                          <option value="Premium">Premium</option>\n                          <option value="Paid">Paid</option>\n                        </select>\n                      </div>\n                    </div>\n                    <div class="a9d">\n                      <div class="a80">\n                        <label for="ed-creator" class="a78">Creator</label>\n                        <input id="ed-creator" value="{{ ed.creator }}" onchange="{{ edOn.creator }}" class="a9h">\n                      </div>\n                      <div class="a80">\n                        <label for="ed-license" class="a78">Licence</label>\n                        <input id="ed-license" value="{{ ed.license }}" onchange="{{ edOn.license }}" placeholder="As stated on the source" class="a9h">\n                      </div>\n                    </div>\n                    <div class="a9i">\n                      <div class="a80">\n                        <label for="ed-commercial" class="a78">Commercial use</label>\n                        <select id="ed-commercial" value="{{ ed.commercial }}" onchange="{{ edOn.commercial }}" class="a9g">\n                          <option value="yes">Allowed</option>\n                          <option value="check">Check the source</option>\n                          <option value="no">Reference only</option>\n                        </select>\n                      </div>\n                      <div class="a80">\n                        <span class="a78">Last checked</span>\n                        <span class="a9j"><span style="color:{{ edCheckColor }}">{{ edCheckLabel }}</span><button type="button" onclick="{{ edMarkChecked }}" class="a91"><i class="ph ph-calendar-check" aria-hidden="true"></i>Checked today</button></span>\n                      </div>\n                    </div>\n                    <fieldset class="a45">\n                      <legend class="a9l">Works with</legend>\n                      <div class="a9m">\n                        <template data-sc="for" list="{{ edTools }}" as="o">\n                          <button type="button" onclick="{{ o.toggle }}" aria-pressed="{{ o.aria }}" style="color:{{ o.fg }};background:{{ o.bg }}" class="a9n">{{ o.label }}</button>\n                        </template>\n                      </div>\n                    </fieldset>\n                    <div class="a77">\n                      <label for="ed-desc" class="a78">Short description</label>\n                      <textarea id="ed-desc" rows="3" value="{{ ed.desc }}" onchange="{{ edOn.desc }}" aria-invalid="{{ edAria.desc }}" style="border:1.5px solid {{ edBorder.desc }}" class="a9o"></textarea>\n                      <span class="a7a">{{ edErr.desc }}</span>\n                    </div>\n                    <div class="a77">\n                      <label for="ed-tags" class="a78">Tags <span class="a7f">(comma separated)</span></label>\n                      <input id="ed-tags" value="{{ ed.tags }}" onchange="{{ edOn.tags }}" class="a9h">\n                    </div>\n                    <div class="a77">\n                      <label for="ed-features" class="a78">What\'s included <span class="a7f">(one per line)</span></label>\n                      <textarea id="ed-features" rows="3" value="{{ ed.features }}" onchange="{{ edOn.features }}" class="a9p"></textarea>\n                    </div>\n                    <div class="a77">\n                      <label for="ed-formats" class="a78">Formats</label>\n                      <input id="ed-formats" value="{{ ed.formats }}" onchange="{{ edOn.formats }}" placeholder="Figma, SVG, React" class="a9h">\n                    </div>\n                    <label class="a9q"><input type="checkbox" checked="{{ ed.featured }}" onchange="{{ edToggleFeatured }}" class="a9r"><span>Show in "Worth starting with" on the home page</span></label>\n                    <div>\n                      <p class="a9s">Live card preview</p>\n                      <div class="a9t">\n                        <div><div class="a26">\n  <button type="button" onclick="{{ edPreview.open }}" class="a27">\n    <template data-sc="if" value="{{ edPreview.typographic }}" hint-placeholder-val="{{ true }}">\n      <div style="color:{{ edPreview.coverFg }};background:{{ edPreview.coverBg }}" class="a28">\n        <span class="a29"><i class="ph {{ edPreview.icon }} ab" aria-hidden="true"></i><span>{{ edPreview.catLabel }}</span></span>\n        <span class="a2a">\n          <span class="a2b">{{ edPreview.name }}</span>\n          <span class="a2c"><img src="{{ edPreview.logo }}" alt="" width="32" height="32" loading="lazy" decoding="async" class="a2d"></span>\n        </span>\n        <template data-sc="if" value="{{ edPreview.shot }}"><img src="{{ edPreview.shot }}" srcset="{{ edPreview.shotSet }}" sizes="(min-width: 640px) 320px, 100vw" width="480" height="300" alt="{{ edPreview.shotAlt }}" loading="lazy" decoding="async" fetchpriority="low" crossorigin="anonymous" data-raw="{{ edPreview.shotRaw }}" onload="{{ edPreview.shotLoad }}" onerror="{{ edPreview.shotErr }}" class="a2e"><span aria-hidden="true" class="a2f"></span></template>\n      <template data-sc="if" value="{{ edPreview.shot }}">\n        <span class="a2g"><i class="ph {{ edPreview.icon }} a2h" aria-hidden="true"></i>{{ edPreview.catLabel }}</span>\n      </template>\n      </div>\n      <template data-sc="if" value="{{ edPreview.shot }}">\n        <div class="a2i">\n          <span class="a2j">{{ edPreview.name }}</span>\n          <template data-sc="if" value="{{ edPreview.hasCreator }}"><span class="a2k">by {{ edPreview.creator }}</span></template>\n        </div>\n      </template>\n      <template data-sc="if" value="{{ edPreview.noShot }}">\n        <template data-sc="if" value="{{ edPreview.hasCreator }}"><div class="a2l">by {{ edPreview.creator }}</div></template>\n      </template>\n    </template>\n    <template data-sc="if" value="{{ edPreview.placeholder }}">\n      <div class="a2m">\n        <span class="a2n">preview image · {{ edPreview.domain }}</span>\n      </div>\n      <div class="a2i">\n        <span class="a2o">{{ edPreview.catLabel }}</span>\n        <span class="a2p">{{ edPreview.name }}</span>\n        <template data-sc="if" value="{{ edPreview.hasCreator }}"><span class="a1e">by {{ edPreview.creator }}</span></template>\n      </div>\n    </template>\n    <div class="a2q">\n      <p class="a2r">{{ edPreview.desc }}</p>\n    </div>\n    <div class="a2s">\n      <span class="a2t">\n        <span class="a2u">{{ edPreview.price }}</span>\n        <span title="{{ edPreview.comLabel }}" style="color:{{ edPreview.comFg }}" class="a2v"><i class="ph {{ edPreview.comIcon }} a2h" aria-hidden="true"></i>{{ edPreview.comLabel }}</span>\n      </span>\n      <template data-sc="if" value="{{ edPreview.hasTools }}"><span class="a2w">{{ edPreview.toolsShort }}</span></template>\n    </div>\n  </button>\n  <template data-sc="if" value="{{ edPreview.canSave }}">\n    <button type="button" onclick="{{ edPreview.toggleSave }}" aria-pressed="{{ edPreview.savedAria }}" aria-label="{{ edPreview.saveLabel }}" title="{{ edPreview.saveLabel }}" style="color:{{ edPreview.saveFg }};background:{{ edPreview.saveBg }};border:1.5px solid {{ edPreview.saveBorder }}" class="a2x"><i class="ph {{ edPreview.saveIcon }} ae" aria-hidden="true"></i></button>\n  </template>\n</div></div>\n                      </div>\n                    </div>\n                    <div class="a9u">\n                      <button type="submit" class="a9v"><i class="ph ph-check" aria-hidden="true"></i>{{ edSaveLabel }}</button>\n                      <button type="button" onclick="{{ closeEditor }}" class="a73">Cancel</button>\n                    </div>\n                  </form>\n                </template>\n              </div>\n            </div>\n          </template>\n\n          <template data-sc="if" value="{{ tabCats }}">\n            <div class="a8j">\n              <div class="a8k">\n                <div class="a9w">\n                  <p class="a9x">Categories appear in this order across the site.</p>\n                  <button type="button" onclick="{{ newCat }}" class="a9y"><i class="ph ph-plus" aria-hidden="true"></i>Add category</button>\n                </div>\n                <ul class="a9z">\n                  <template data-sc="for" list="{{ catRows }}" as="c" hint-placeholder-count="10">\n                    <li style="background:{{ c.bg }}" class="a8v">\n                      <span class="aa0"><i class="ph {{ c.icon }} ae" aria-hidden="true"></i></span>\n                      <span class="a8w"><span class="a78">{{ c.label }}</span><span class="a1e">{{ c.countLabel }}</span></span>\n                      <span class="a90">\n                        <button type="button" onclick="{{ c.up }}" disabled="{{ c.first }}" aria-label="{{ c.upAria }}" style="opacity:{{ c.upOp }}" class="aa1"><i class="ph ph-arrow-up" aria-hidden="true"></i></button>\n                        <button type="button" onclick="{{ c.down }}" disabled="{{ c.last }}" aria-label="{{ c.downAria }}" style="opacity:{{ c.downOp }}" class="aa1"><i class="ph ph-arrow-down" aria-hidden="true"></i></button>\n                        <button type="button" onclick="{{ c.edit }}" class="a91"><i class="ph ph-pencil-simple" aria-hidden="true"></i>Edit</button>\n                        <button type="button" onclick="{{ c.del }}" aria-label="{{ c.delAria }}" class="aa2"><i class="ph ph-trash ab" aria-hidden="true"></i></button>\n                      </span>\n                      <template data-sc="if" value="{{ c.hasMsg }}">\n                        <p role="alert" class="aa3">{{ c.msg }}</p>\n                      </template>\n                      <template data-sc="if" value="{{ c.confirming }}">\n                        <span class="aa4">Delete this empty category?\n                          <button type="button" onclick="{{ c.confirmDel }}" class="a8y">Delete</button>\n                          <button type="button" onclick="{{ c.cancelDel }}" class="a8z">Keep</button>\n                        </span>\n                      </template>\n                    </li>\n                  </template>\n                </ul>\n              </div>\n              <div class="aa5">\n                <template data-sc="if" value="{{ noCatEditor }}" hint-placeholder-val="{{ true }}">\n                  <div class="a96">\n                    <i class="ph ph-folder-simple-plus a6m" aria-hidden="true"></i>\n                    <p class="a97">Edit a category\'s name, description and icon, or add a new one. Categories with resources can\'t be deleted until those resources are moved.</p>\n                  </div>\n                </template>\n                <template data-sc="if" value="{{ hasCatEditor }}">\n                  <form novalidate="" onsubmit="{{ saveCat }}" class="aa6">\n                    <h2 class="a34">{{ ceTitle }}</h2>\n                    <div class="a77">\n                      <label for="ce-label" class="a78">Name</label>\n                      <input id="ce-label" value="{{ ce.label }}" onchange="{{ ceOn.label }}" aria-invalid="{{ ceAria.label }}" style="border:1.5px solid {{ ceBorder.label }}" class="a9c">\n                      <span class="a7a">{{ ceErr.label }}</span>\n                    </div>\n                    <div class="a77">\n                      <label for="ce-short" class="a78">Short name <span class="a7f">(used in project sets, e.g. "Icons")</span></label>\n                      <input id="ce-short" value="{{ ce.short }}" onchange="{{ ceOn.short }}" class="a9h">\n                    </div>\n                    <div class="a77">\n                      <label for="ce-blurb" class="a78">One-line description</label>\n                      <textarea id="ce-blurb" rows="2" value="{{ ce.blurb }}" onchange="{{ ceOn.blurb }}" class="a9p"></textarea>\n                    </div>\n                    <fieldset class="a45">\n                      <legend class="a9l">Icon</legend>\n                      <div class="aa7">\n                        <template data-sc="for" list="{{ iconChoices }}" as="ic">\n                          <button type="button" onclick="{{ ic.pick }}" aria-pressed="{{ ic.aria }}" aria-label="{{ ic.name }}" style="color:{{ ic.fg }};background:{{ ic.bg }};border:1.5px solid {{ ic.border }}" class="aa8"><i class="ph {{ ic.name }} a1z" aria-hidden="true"></i></button>\n                        </template>\n                      </div>\n                    </fieldset>\n                    <div class="aa9">\n                      <span class="aaa"><i class="ph {{ ce.icon }} a1z" aria-hidden="true"></i></span>\n                      <span class="aab"><span class="a78">{{ cePreviewLabel }}</span><span class="aac">{{ ce.blurb }}</span></span>\n                    </div>\n                    <div class="a8c">\n                      <button type="submit" class="a9v"><i class="ph ph-check" aria-hidden="true"></i>Save category</button>\n                      <button type="button" onclick="{{ closeCat }}" class="a73">Cancel</button>\n                    </div>\n                  </form>\n                </template>\n              </div>\n            </div>\n          </template>\n\n          <template data-sc="if" value="{{ tabSubs }}">\n            <template data-sc="if" value="{{ subsEmpty }}">\n              <div class="aad">\n                <i class="ph ph-tray a53" aria-hidden="true"></i>\n                <p class="a6c">No submissions waiting. Anything sent through the Submit page lands here for review.</p>\n              </div>\n            </template>\n            <ul class="aae">\n              <template data-sc="for" list="{{ subRows }}" as="x">\n                <li class="aaf">\n                  <div class="aag"><strong class="ab">{{ x.name }}</strong><span class="a1e">{{ x.meta }}</span></div>\n                  <a href="{{ x.url }}" target="_blank" rel="noopener noreferrer" class="aah">{{ x.url }}</a>\n                  <p class="a70">{{ x.desc }}</p>\n                  <div class="a3d">\n                    <button type="button" onclick="{{ x.review }}" class="a9y"><i class="ph ph-note-pencil" aria-hidden="true"></i>Review in editor</button>\n                    <button type="button" onclick="{{ x.dismiss }}" class="a8e">Dismiss</button>\n                  </div>\n                </li>\n              </template>\n            </ul>\n          </template>\n\n          <template data-sc="if" value="{{ tabSite }}">\n            <form novalidate="" onsubmit="{{ saveSite }}" class="aai">\n              <h2 class="a34">Footer and site details</h2>\n              <div class="a77">\n                <label for="st-copy" class="a78">Copyright holder</label>\n                <input id="st-copy" value="{{ st.copy }}" onchange="{{ stOn.copy }}" class="a9h">\n              </div>\n              <div class="a77">\n                <label for="st-address" class="a78">Address <span class="a7f">(shown in the footer)</span></label>\n                <textarea id="st-address" rows="2" value="{{ st.address }}" onchange="{{ stOn.address }}" class="a9p"></textarea>\n              </div>\n              <fieldset class="aaj">\n                <legend class="aak">Social links <span class="a7f">(leave empty to hide)</span></legend>\n                <template data-sc="for" list="{{ siteSocials }}" as="so">\n                  <div class="aal">\n                    <label for="{{ so.id }}" class="aam"><i class="ph {{ so.icon }} ae" aria-hidden="true"></i>{{ so.label }}</label>\n                    <input id="{{ so.id }}" type="url" value="{{ so.value }}" onchange="{{ so.on }}" placeholder="https://" style="border:1.5px solid {{ so.border }}" class="aan">\n                    <template data-sc="if" value="{{ so.hasErr }}"><span class="aao">{{ so.err }}</span></template>\n                  </div>\n                </template>\n              </fieldset>\n              <button type="submit" class="aap"><i class="ph ph-check" aria-hidden="true"></i>Save site details</button>\n            </form>\n          </template>\n\n          <template data-sc="if" value="{{ tabJson }}">\n            <div class="aaq">\n              <div class="aar">\n                <div class="aas">\n                  <label class="aat"><input type="checkbox" checked="{{ jsonLive }}" onchange="{{ toggleJsonLive }}" class="a9r">Apply valid changes as I type</label>\n                  <span class="a9m">\n                    <button type="button" onclick="{{ formatJson }}" class="a8z">Format</button>\n                    <button type="button" onclick="{{ revertJson }}" class="a8z">Revert</button>\n                    <template data-sc="if" value="{{ jsonManual }}">\n                      <button type="button" onclick="{{ applyJson }}" disabled="{{ jsonInvalid }}" style="opacity:{{ applyOp }}" class="aau">Apply to site</button>\n                    </template>\n                  </span>\n                </div>\n                <label for="json-ed" class="a15">Catalog JSON</label>\n                <textarea id="json-ed" spellcheck="false" value="{{ jsonDraft }}" onchange="{{ onJson }}" aria-describedby="json-status" style="border:1.5px solid {{ jsonBorder }}" class="aav"></textarea>\n                <p id="json-status" role="status" style="color:{{ jsonStatusColor }}" class="aaw"><i class="ph {{ jsonStatusIcon }} aax" aria-hidden="true"></i><span>{{ jsonStatus }}</span></p>\n                <p class="a9x">Shape: categories, resources, collections, featured and submissions. Each resource needs id, name, cat (a category id) and url. Collections are edited here.</p>\n              </div>\n              <div class="aay">\n                <div class="aaz">\n                  <h2 class="ab0"><i class="ph ph-eye" aria-hidden="true"></i>Preview of the draft</h2>\n                  <span class="a1e">{{ pvSummary }}</span>\n                </div>\n                <div class="ab1">\n                  <template data-sc="if" value="{{ pvInvalid }}">\n                    <p class="a70">The preview holds the last valid version until the JSON parses again.</p>\n                  </template>\n                  <ol class="a9z">\n                    <template data-sc="for" list="{{ pvCats }}" as="c">\n                      <li class="ab2"><i class="ph {{ c.icon }} ab" aria-hidden="true"></i><span class="ab3">{{ c.label }}</span><span class="ab4">{{ c.count }}</span></li>\n                    </template>\n                  </ol>\n                  <div class="ab5">\n                    <template data-sc="for" list="{{ pvCards }}" as="item">\n                      <div><div class="a26">\n  <button type="button" onclick="{{ item.open }}" class="a27">\n    <template data-sc="if" value="{{ item.typographic }}" hint-placeholder-val="{{ true }}">\n      <div style="color:{{ item.coverFg }};background:{{ item.coverBg }}" class="a28">\n        <span class="a29"><i class="ph {{ item.icon }} ab" aria-hidden="true"></i><span>{{ item.catLabel }}</span></span>\n        <span class="a2a">\n          <span class="a2b">{{ item.name }}</span>\n          <span class="a2c"><img src="{{ item.logo }}" alt="" width="32" height="32" loading="lazy" decoding="async" class="a2d"></span>\n        </span>\n        <template data-sc="if" value="{{ item.shot }}"><img src="{{ item.shot }}" srcset="{{ item.shotSet }}" sizes="(min-width: 640px) 320px, 100vw" width="480" height="300" alt="{{ item.shotAlt }}" loading="lazy" decoding="async" fetchpriority="low" crossorigin="anonymous" data-raw="{{ item.shotRaw }}" onload="{{ item.shotLoad }}" onerror="{{ item.shotErr }}" class="a2e"><span aria-hidden="true" class="a2f"></span></template>\n      <template data-sc="if" value="{{ item.shot }}">\n        <span class="a2g"><i class="ph {{ item.icon }} a2h" aria-hidden="true"></i>{{ item.catLabel }}</span>\n      </template>\n      </div>\n      <template data-sc="if" value="{{ item.shot }}">\n        <div class="a2i">\n          <span class="a2j">{{ item.name }}</span>\n          <template data-sc="if" value="{{ item.hasCreator }}"><span class="a2k">by {{ item.creator }}</span></template>\n        </div>\n      </template>\n      <template data-sc="if" value="{{ item.noShot }}">\n        <template data-sc="if" value="{{ item.hasCreator }}"><div class="a2l">by {{ item.creator }}</div></template>\n      </template>\n    </template>\n    <template data-sc="if" value="{{ item.placeholder }}">\n      <div class="a2m">\n        <span class="a2n">preview image · {{ item.domain }}</span>\n      </div>\n      <div class="a2i">\n        <span class="a2o">{{ item.catLabel }}</span>\n        <span class="a2p">{{ item.name }}</span>\n        <template data-sc="if" value="{{ item.hasCreator }}"><span class="a1e">by {{ item.creator }}</span></template>\n      </div>\n    </template>\n    <div class="a2q">\n      <p class="a2r">{{ item.desc }}</p>\n    </div>\n    <div class="a2s">\n      <span class="a2t">\n        <span class="a2u">{{ item.price }}</span>\n        <span title="{{ item.comLabel }}" style="color:{{ item.comFg }}" class="a2v"><i class="ph {{ item.comIcon }} a2h" aria-hidden="true"></i>{{ item.comLabel }}</span>\n      </span>\n      <template data-sc="if" value="{{ item.hasTools }}"><span class="a2w">{{ item.toolsShort }}</span></template>\n    </div>\n  </button>\n  <template data-sc="if" value="{{ item.canSave }}">\n    <button type="button" onclick="{{ item.toggleSave }}" aria-pressed="{{ item.savedAria }}" aria-label="{{ item.saveLabel }}" title="{{ item.saveLabel }}" style="color:{{ item.saveFg }};background:{{ item.saveBg }};border:1.5px solid {{ item.saveBorder }}" class="a2x"><i class="ph {{ item.saveIcon }} ae" aria-hidden="true"></i></button>\n  </template>\n</div></div>\n                    </template>\n                  </div>\n                </div>\n              </div>\n            </div>\n          </template>\n        </div>\n      </div>\n    </template>\n    <template data-sc="if" value="{{ isShortlist }}">\n      <div data-screen-label="Shortlist" class="ab6">\n        <div class="ab7">\n          <div class="a83">\n            <h1 class="a3u">Shortlist</h1>\n            <p class="ab8">Compare pricing, commercial use and tools side by side before you leave for a source. Saved in this browser.</p>\n          </div>\n          <template data-sc="if" value="{{ slHas }}">\n            <div class="a4b">\n              <button type="button" onclick="{{ goExplore }}" class="ab9"><i class="ph ph-plus" aria-hidden="true"></i>Add more</button>\n              <button type="button" onclick="{{ slAskClear }}" class="aba"><i class="ph ph-trash" aria-hidden="true"></i>Clear shortlist</button>\n            </div>\n          </template>\n        </div>\n        <template data-sc="if" value="{{ slConfirm }}">\n          <div role="alert" class="abb">\n            <span>Remove all {{ slCount }} resources from your shortlist?</span>\n            <span class="a8c"><button type="button" onclick="{{ slClear }}" class="abc">Clear all</button><button type="button" onclick="{{ slCancelClear }}" class="abd">Keep</button></span>\n          </div>\n        </template>\n        <template data-sc="if" value="{{ slEmpty }}">\n          <div class="abe">\n            <i class="ph ph-bookmarks-simple abf" aria-hidden="true"></i>\n            <h2 class="a34">Nothing saved yet</h2>\n            <p class="a70">Use the bookmark on any resource card, or "Compare this set" on a project, to line resources up here.</p>\n            <button type="button" onclick="{{ goExplore }}" class="abg">Browse resources</button>\n          </div>\n        </template>\n        <template data-sc="if" value="{{ slHas }}">\n          <div class="abh">\n            <table style="min-width:{{ slMinW }}" class="abi">\n              <caption class="a15">Shortlisted resources compared</caption>\n              <thead>\n                <tr>\n                  <th scope="col" class="abj">{{ slCountLabel }}</th>\n                  <template data-sc="for" list="{{ slCols }}" as="c">\n                    <th scope="col" class="abk">\n                      <div class="abl">\n                        <span class="abm">\n                          <span class="abn"><i class="ph {{ c.icon }}" aria-hidden="true"></i>{{ c.catLabel }}</span>\n                          <button type="button" onclick="{{ c.open }}" class="abo">{{ c.name }}</button>\n                          <span class="a1e">{{ c.creator }}</span>\n                        </span>\n                        <button type="button" onclick="{{ c.remove }}" aria-label="{{ c.removeAria }}" class="abp"><i class="ph ph-x" aria-hidden="true"></i></button>\n                      </div>\n                    </th>\n                  </template>\n                </tr>\n              </thead>\n              <tbody>\n                <template data-sc="for" list="{{ slRows }}" as="row">\n                  <tr>\n                    <th scope="row" style="background:{{ row.bg }}" class="abq"><span class="a4k"><i class="ph {{ row.icon }} ab4" aria-hidden="true"></i>{{ row.label }}</span></th>\n                    <template data-sc="for" list="{{ row.cells }}" as="cell">\n                      <td style="font-weight:{{ cell.weight }};color:{{ cell.color }};background:{{ row.bg }}" class="abr">\n                        <template data-sc="if" value="{{ cell.isText }}"><span class="abs"><template data-sc="if" value="{{ cell.hasIcon }}"><i class="ph {{ cell.icon }} abt" aria-hidden="true"></i></template><span>{{ cell.text }}</span></span></template>\n                        <template data-sc="if" value="{{ cell.isLink }}"><a href="{{ cell.url }}" target="_blank" rel="noopener noreferrer" class="abu">{{ cell.text }}<i class="ph ph-arrow-square-out" aria-hidden="true"></i><span class="a15"> (opens in a new tab)</span></a></template>\n                      </td>\n                    </template>\n                  </tr>\n                </template>\n              </tbody>\n            </table>\n          </div>\n          <p class="abv">Licence details are summaries of what each source published. Confirm on the source before commercial use.</p>\n        </template>\n      </div>\n    </template>\n\n    <template data-sc="if" value="{{ isLegal }}">\n      <article data-screen-label="Legal" class="abw">\n        <h1 class="a6s">{{ legal.title }}</h1>\n        <p class="abx">{{ legal.updated }}</p>\n        <p class="aby"><i class="ph ph-info a8a" aria-hidden="true"></i><span>Draft for review. This describes how the site works today. Have it checked by a qualified person before launch.</span></p>\n        <template data-sc="for" list="{{ legal.sections }}" as="x">\n          <section class="abz">\n            <h2 class="ac0">{{ x.h }}</h2>\n            <p class="ac1">{{ x.p }}</p>\n          </section>\n        </template>\n        <p class="ac2">Questions about this page? <button type="button" onclick="{{ goContact }}" class="a5a">Use the contact form</button>.</p>\n      </article>\n    </template>\n\n    <template data-sc="if" value="{{ isSettings }}">\n      <article data-screen-label="Settings" class="ac3">\n        <h1 class="a6s">Settings</h1>\n        <p class="ac4">Change how Design Atlas looks on this device. Changes apply straight away and stay in this browser.</p>\n        <section aria-labelledby="set-display" class="ac5">\n          <div class="a77">\n            <h2 id="set-display" class="a34">Display</h2>\n            <p class="a7u">Theme and text size. Every page supports each option.</p>\n          </div>\n          <div class="ac6">\n            <fieldset class="ac7">\n              <legend class="ac8">Theme</legend>\n              <template data-sc="for" list="{{ themeOpts }}" as="o" hint-placeholder-count="3">\n                <label for="{{ o.inputId }}" style="border:{{ o.bw }} solid {{ o.border }}" class="ac9"><input type="radio" name="theme" id="{{ o.inputId }}" checked="{{ o.checked }}" onchange="{{ o.onChange }}" class="aca"><span class="ak">{{ o.label }}</span><i class="ph {{ o.icon }} ae" aria-hidden="true"></i></label>\n              </template>\n            </fieldset>\n            <fieldset class="ac7">\n              <legend class="ac8">Text size</legend>\n              <template data-sc="for" list="{{ textOpts }}" as="o" hint-placeholder-count="3">\n                <label for="{{ o.inputId }}" style="border:{{ o.bw }} solid {{ o.border }}" class="ac9"><input type="radio" name="text-size" id="{{ o.inputId }}" checked="{{ o.checked }}" onchange="{{ o.onChange }}" class="aca"><span class="ak">{{ o.label }}</span><span aria-hidden="true" style="font-size:{{ o.fs }}" class="acb">Aa</span></label>\n              </template>\n            </fieldset>\n          </div>\n        </section>\n        <section aria-labelledby="set-data" class="acc">\n          <div class="a77">\n            <h2 id="set-data" class="a34">Saved data</h2>\n            <p class="a7u">Your shortlist, Manage edits and these settings stay in this browser. Nothing is sent to a server.</p>\n          </div>\n          <div class="acd">\n            <button type="button" onclick="{{ goShortlist }}" class="ace"><i class="ph ph-bookmarks-simple ab" aria-hidden="true"></i>View shortlist ({{ slCountAll }})</button>\n            <button type="button" onclick="{{ openCookies }}" class="ace"><i class="ph ph-cookie ab" aria-hidden="true"></i>Cookie settings and stored data</button>\n          </div>\n        </section>\n      </article>\n    </template>\n  </main>\n\n  <footer id="site-footer" class="acf">\n    <div class="acg">\n      <button type="button" onclick="{{ toTop }}" aria-label="Back to top" class="ach"><i class="ph ph-arrow-up a1z" aria-hidden="true"></i></button>\n      <div class="aci">\n        <div class="acj">\n          <h2 class="ack">New entries, once a month</h2>\n          <p class="acl">A short email listing what was added to the index, with licences.</p>\n        </div>\n        <div class="acm">\n          <template data-sc="if" value="{{ nlSent }}">\n            <p role="status" class="acn"><i class="ph ph-check-circle ae" aria-hidden="true"></i>Subscribed. Check {{ nl }} for a confirmation link.</p>\n          </template>\n          <template data-sc="if" value="{{ nlShowForm }}" hint-placeholder-val="{{ true }}">\n            <form novalidate="" onsubmit="{{ nlSubmit }}">\n              <label for="nl-email" class="aco">Email address</label>\n              <div class="acp">\n                <input id="nl-email" type="email" autocomplete="email" value="{{ nl }}" onchange="{{ onNl }}" placeholder="email@example.com" aria-invalid="{{ nlAria }}" aria-describedby="nl-err" style="border:2px solid {{ nlBorder }}" class="acq">\n                <button type="submit" disabled="{{ nlSending }}" class="acr">{{ nlBtn }}</button>\n              </div>\n              <p id="nl-err" role="alert" class="acs">{{ nlErr }}</p>\n            </form>\n          </template>\n        </div>\n      </div>\n\n      <div class="act">\n        <div class="acu">\n          <span class="a1o"><i class="ph ph-compass-rose a3t" aria-hidden="true"></i><span class="acv">Design Atlas</span></span>\n          <p class="acw">An index of design resources, each listed with its creator and licence.</p>\n          <template data-sc="if" value="{{ hasSocials }}">\n            <ul aria-label="Social links" class="acx">\n              <template data-sc="for" list="{{ socials }}" as="so">\n                <li><a href="{{ so.url }}" target="_blank" rel="noopener noreferrer" aria-label="{{ so.aria }}" class="acy"><i class="ph {{ so.icon }} ae" aria-hidden="true"></i></a></li>\n              </template>\n            </ul>\n          </template>\n        </div>\n        <template data-sc="for" list="{{ footerGroups }}" as="g" hint-placeholder-count="3">\n          <nav aria-label="{{ g.title }}" class="acz">\n            <h3 class="ad0">{{ g.title }}</h3>\n            <template data-sc="for" list="{{ g.links }}" as="n">\n              <button type="button" onclick="{{ n.go }}" class="ad1">{{ n.label }}</button>\n            </template>\n          </nav>\n        </template>\n      </div>\n\n      <div class="ad2">\n        <div class="ad3">\n          <span>© {{ year }} {{ copyName }}. All rights reserved.</span>\n          <template data-sc="if" value="{{ hasAddress }}"><span>{{ addressText }}</span></template>\n          <span class="ad4">Design Atlas lists resources by other creators. Names and trademarks belong to their owners. Icons by Phosphor (MIT).</span>\n        </div>\n        <nav aria-label="Legal" class="ad5">\n          <button type="button" onclick="{{ goPrivacy }}" class="ad6"><i class="ph ph-shield-check a4e" aria-hidden="true"></i>Privacy policy</button>\n          <button type="button" onclick="{{ goTerms }}" class="ad6"><i class="ph ph-file-text a4e" aria-hidden="true"></i>Terms and conditions</button>\n          <button type="button" onclick="{{ openCookies }}" class="ad6"><i class="ph ph-cookie a4e" aria-hidden="true"></i>Cookie settings</button>\n        </nav>\n      </div>\n    </div>\n  </footer>\n\n  <button type="button" onclick="{{ toTop }}" aria-label="Back to top" tabindex="{{ toTopTab }}" aria-hidden="{{ toTopHidden }}" style="opacity:{{ toTopOp }};transform:translateY({{ toTopY }});transition:opacity .2s ease, transform .2s ease, visibility 0s linear {{ toTopDelay }};visibility:{{ toTopVis }}" class="ad7"><i class="ph ph-arrow-up a1z" aria-hidden="true"></i></button>\n\n  <template data-sc="if" value="{{ cookieOpen }}">\n    <div onclick="{{ closeCookies }}" aria-hidden="true" class="ad8"></div>\n    <div role="dialog" aria-modal="true" aria-labelledby="ck-h" id="cookie-dialog" class="ad9">\n      <div class="a99">\n        <h2 id="ck-h" class="ada"><i class="ph ph-cookie" aria-hidden="true"></i>Cookie settings</h2>\n        <button type="button" onclick="{{ closeCookies }}" aria-label="Close cookie settings" class="adb"><i class="ph ph-x ae" aria-hidden="true"></i></button>\n      </div>\n      <p class="a70">Design Atlas uses your browser\'s storage only for things you ask it to do. Nothing here is used for advertising.</p>\n      <div class="adc">\n        <div><strong>Necessary storage</strong><p class="add">Keeps your shortlist, catalog edits made in Manage, the submissions queue and this choice.</p></div>\n        <span class="ade">Always on</span>\n      </div>\n      <div class="adc">\n        <div><strong id="ck-an">Analytics</strong><p class="add">No analytics are installed yet. Your choice is saved and applied if they\'re added later.</p></div>\n        <button type="button" role="switch" aria-checked="{{ ckAria }}" aria-labelledby="ck-an" onclick="{{ toggleAnalytics }}" style="background:{{ ckTrack }}" class="adf"><span style="left:{{ ckKnob }}" class="adg"></span></button>\n      </div>\n      <template data-sc="if" value="{{ clearConfirm }}">\n        <div role="alert" class="adh">\n          <span class="adi">This removes your shortlist, local catalog edits and submissions. Export them first if you need them.</span>\n          <span class="a8c"><button type="button" onclick="{{ doClear }}" class="abc">Clear data</button><button type="button" onclick="{{ cancelClear }}" class="abd">Keep</button></span>\n        </div>\n      </template>\n      <div class="adj">\n        <button type="button" onclick="{{ askClear }}" class="adk">Clear data on this device</button>\n        <button type="button" onclick="{{ saveCookies }}" class="adl">Save choices</button>\n      </div>\n    </div>\n  </template>\n\n  <div role="status" aria-live="polite" style="background:{{ toastBg }};opacity:{{ toastOp }};transform:translate(-50%,{{ toastY }});visibility:{{ toastVis }}" class="adm"><i class="ph {{ toastIcon }} ae" aria-hidden="true"></i><span>{{ toastMsg }}</span></div>\n</div>\n';